try {
  var trigger = $('Execute Workflow Trigger').first().json;
  var cfg = $('⚙️ Client Config').first().json;
  var toolInput = trigger.toolInput || {};
  var toolUseId = trigger.toolUseId || '';
  var phone = trigger.phone || '';
  var rawDate = (toolInput.date || '').toString().toLowerCase().trim();
  var time = (toolInput.time || '9am').toLowerCase();
  var service = toolInput.service || '';
  var address = toolInput.address || '';
  var name = toolInput.name || '';
  var email = toolInput.email || '';

  var timeMap = { '9am': 9, '10am': 10, '11am': 11, '12pm': 12, '1pm': 13, '2pm': 14, '3pm': 15, '4pm': 16, '5pm': 17 };
  // BUG-R41: an unmapped time string used to silently become 9am while the sheet
  // recorded the customer's own wording — calendar and CRM would disagree and nobody
  // would know. Today the model normalises "14:00" to "2pm" before calling, but the
  // code must not depend on that. Refuse instead of guessing.
  var localHour = timeMap[time];
  var timeUnrecognised = false;
  if (localHour === undefined) { localHour = 9; timeUnrecognised = true; }

  var now = new Date();
  var dateObj = null;

  if (/^\d{4}-\d{2}-\d{2}$/.test(rawDate)) {
    dateObj = new Date(rawDate + 'T12:00:00Z');
  } else if (rawDate === 'today') {
    dateObj = new Date(now.getTime());
  } else if (rawDate === 'tomorrow') {
    dateObj = new Date(now.getTime());
    dateObj.setUTCDate(dateObj.getUTCDate() + 1);
  } else if (rawDate) {
    // BUG-R31: an explicit day+month ("Monday, 17 August") must beat the weekday name.
    // Matching 'monday' first made "Monday 24 August" silently book the NEAREST Monday.
    var monthWords = ['january','february','march','april','may','june','july','august','september','october','november','december'];
    var mIdx = -1;
    for (var mw = 0; mw < monthWords.length; mw++) {
      if (rawDate.indexOf(monthWords[mw]) !== -1) { mIdx = mw; break; }
    }
    var dayNumMatch = rawDate.match(/(\d{1,2})\s*(?:st|nd|rd|th)?/);
    var dayNum = dayNumMatch ? parseInt(dayNumMatch[1], 10) : 0;
    if (mIdx !== -1 && dayNum >= 1 && dayNum <= 31) {
      var yr = now.getUTCFullYear();
      var cand = new Date(Date.UTC(yr, mIdx, dayNum, 12, 0, 0));
      // A date already well past this year means they mean next year.
      if (cand.getTime() < now.getTime() - 86400000) { cand = new Date(Date.UTC(yr + 1, mIdx, dayNum, 12, 0, 0)); }
      dateObj = cand;
    }
    var dayNamesLower = ['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
    var foundIdx = -1;
    for (var d = 0; d < dayNamesLower.length; d++) {
      if (rawDate.indexOf(dayNamesLower[d]) !== -1) { foundIdx = d; break; }
    }
    if (dateObj) {
      foundIdx = -1;
    }
    if (foundIdx !== -1) {
      var currentDay = now.getUTCDay();
      var daysUntil = (foundIdx - currentDay + 7) % 7;
      if (daysUntil === 0) { daysUntil = 7; }
      dateObj = new Date(now.getTime());
      dateObj.setUTCDate(dateObj.getUTCDate() + daysUntil);
    } else {
      var attempt = new Date(rawDate);
      // Must not clobber a date already resolved above.
      if (!dateObj && !isNaN(attempt.getTime())) { dateObj = attempt; }
    }
  }

  // V8's legacy parser defaults a yearless string like "24 august" to the year 2001.
  if (dateObj && !isNaN(dateObj.getTime()) && dateObj.getUTCFullYear() < now.getUTCFullYear()) { dateObj = null; }

  if (!dateObj || isNaN(dateObj.getTime())) {
    dateObj = new Date(now.getTime());
    dateObj.setUTCDate(dateObj.getUTCDate() + 1);
  }

  function pad(n) { return n < 10 ? '0' + n : '' + n; }
  var resolvedDate = dateObj.getUTCFullYear() + '-' + pad(dateObj.getUTCMonth() + 1) + '-' + pad(dateObj.getUTCDate());

  var month = dateObj.getUTCMonth() + 1;
  var isBST = (month >= 3 && month <= 10);
  var utcOffset = isBST ? 1 : 0;
  var utcHour = localHour - utcOffset;

  var startISO = resolvedDate + 'T' + pad(utcHour) + ':00:00.000Z';
  var endISO = resolvedDate + 'T' + pad(utcHour + 1) + ':00:00.000Z';

  var days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  var months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  var friendlyDate = days[dateObj.getUTCDay()] + ', ' + dateObj.getUTCDate() + ' ' + months[dateObj.getUTCMonth()];
  var slotLabel = time.charAt(0).toUpperCase() + time.slice(1);

  // ---- FINDING-R30 write-side gate ----
  // The model can call book_house_visit without ever calling check_availability,
  // so opening hours must be enforced here too, not only on the read path.
  function parseSlots(s) {
    var out = [];
    var parts = (s || '').split(',');
    for (var i = 0; i < parts.length; i++) {
      var v = parseInt(parts[i], 10);
      if (!isNaN(v)) { out.push(v); }
    }
    return out;
  }
  var dow = dateObj.getUTCDay();
  var allowed;
  if (dow === 0) { allowed = parseSlots(cfg.sundaySlots); }
  else if (dow === 6) { allowed = parseSlots(cfg.saturdaySlots); }
  else { allowed = parseSlots(cfg.weekdaySlots); }

  var bookable = true;
  var rejectReason = '';

  var bankHolidays = (cfg.bankHolidays || '').split(',');
  for (var b = 0; b < bankHolidays.length; b++) {
    if (bankHolidays[b].trim() === resolvedDate) { bookable = false; rejectReason = 'bank-holiday'; break; }
  }
  if (bookable && allowed.length === 0) { bookable = false; rejectReason = 'closed-day'; }
  if (bookable) {
    var inList = false;
    for (var a = 0; a < allowed.length; a++) { if (allowed[a] === localHour) { inList = true; break; } }
    if (!inList) { bookable = false; rejectReason = 'outside-hours'; }
  }
  if (bookable && timeUnrecognised) { bookable = false; rejectReason = 'bad-time'; }
  if (bookable) {
    var minNotice = parseInt(cfg.minNoticeHours, 10);
    if (isNaN(minNotice)) { minNotice = 2; }
    var startMs = new Date(startISO).getTime();
    if (isNaN(startMs) || startMs < now.getTime() + (minNotice * 3600000)) { bookable = false; rejectReason = 'too-soon'; }
  }

  return [{
    json: {
      toolUseId: toolUseId,
      phone: phone,
      name: name,
      email: email,
      service: service,
      address: address,
      date: resolvedDate,
      time: time,
      startISO: startISO,
      endISO: endISO,
      friendlyDate: friendlyDate,
      slotLabel: slotLabel,
      bookable: bookable,
      rejectReason: rejectReason,
      bookedAt: new Date().toISOString()
    }
  }];
} catch (e) {
  var fb = $('Execute Workflow Trigger').first().json;
  return [{
    json: {
      toolUseId: fb.toolUseId || '',
      phone: fb.phone || '',
      error: e.message,
      startISO: '',
      endISO: '',
      friendlyDate: '',
      slotLabel: '',
      bookable: false,
      rejectReason: 'error',
      bookedAt: new Date().toISOString()
    }
  }];
}

try {
  var booking = $('Compute Booking Times').first().json;
  var phone = booking.phone || '';

  // Check appointment log for existing confirmed booking
  var appointments = $('Read Appointment Log').all();
  var isDuplicate = false;
  for (var i = 0; i < appointments.length; i++) {
    var appt = appointments[i].json;
    if (String(appt.Phone).replace(/[^0-9]/g, '') === String(phone).replace(/[^0-9]/g, '') && appt.Status === 'confirmed') {
      isDuplicate = true;
      break;
    }
  }

  // Check Clients for new lead detection
  var clients = $input.all();
  var isNewLead = true;
  for (var j = 0; j < clients.length; j++) {
    if (String(clients[j].json.Phone).replace(/[^0-9]/g, '') === String(phone).replace(/[^0-9]/g, '')) {
      isNewLead = false;
      break;
    }
  }

  return [{
    json: {
      isDuplicate: isDuplicate,
      isNewLead: isNewLead,
      toolUseId: booking.toolUseId || '',
      phone: phone,
      name: booking.name || '',
      email: booking.email || '',
      service: booking.service || '',
      address: booking.address || '',
      date: booking.date || '',
      time: booking.time || '',
      startISO: booking.startISO || '',
      endISO: booking.endISO || '',
      friendlyDate: booking.friendlyDate || '',
      slotLabel: booking.slotLabel || '',
      bookedAt: booking.bookedAt || new Date().toISOString()
    }
  }];
} catch (e) {
  return [{
    json: {
      isDuplicate: false,
      isNewLead: false,
      toolUseId: $('Compute Booking Times').first().json.toolUseId || '',
      phone: $('Compute Booking Times').first().json.phone || '',
      error: e.message
    }
  }];
}

try {
