try {
  var data = $('Process Lookups').first().json;
  var result = 'Your house visit for ' + data.service + ' is booked for ' + data.friendlyDate + ' at ' + data.slotLabel + '. Address: ' + data.address + '. We look forward to seeing you!';
  return [{
    json: {
      toolCallId: data.toolUseId || '',
      result: result
    }
  }];
} catch (e) {
  return [{
    json: {
      toolCallId: $('Process Lookups').first().json.toolUseId || '',
      result: 'Your house visit has been successfully booked. We look forward to seeing you!'
    }
  }];
}

try {
  var data = $('Process Lookups').first().json;
  return [{ json: { toolCallId: data.toolUseId || '', result: 'I was unable to book your appointment due to a calendar system error. Please try again in a moment, or call us directly to book.' } }];
