}

try {
  var events = $input.all();
  var prep = $('Process Lookups').first().json || {};
  var startISO = prep.startISO || '';
  var endISO = prep.endISO || '';

  // BUG-R4 rule: this Calendar node runs with onError=continueRegularOutput, so a
  // failed read arrives here as DATA, not as a thrown error. Decide explicitly.
  var readFailed = false;
  if (events.length > 0 && events[0].json && events[0].json.error) { readFailed = true; }

  if (readFailed) {
    // Cannot verify. Availability was already checked earlier in the conversation,
    // so proceed rather than block a converting customer on a transient blip.
    // This is exactly the pre-existing behaviour — no new risk introduced.
    return [{ json: { slotFree: true, verified: false, note: 'calendar re-check failed; proceeding on the earlier availability check' } }];
  }

  var newStart = new Date(startISO).getTime();
  var newEnd = new Date(endISO).getTime();
  if (isNaN(newStart) || isNaN(newEnd)) {
    return [{ json: { slotFree: true, verified: false, note: 'could not parse requested slot times' } }];
  }

  var clash = false;
  for (var i = 0; i < events.length; i++) {
    var ev = events[i].json || {};
    if (ev.status === 'cancelled') { continue; }
    var s = ev.start ? (ev.start.dateTime || ev.start.date) : null;
    var e = ev.end ? (ev.end.dateTime || ev.end.date) : null;
    if (!s || !e) { continue; }
    var evStart = new Date(s).getTime();
    var evEnd = new Date(e).getTime();
    if (isNaN(evStart) || isNaN(evEnd)) { continue; }
    // Overlap test: existing starts before ours ends AND ends after ours starts.
    if (evStart < newEnd && evEnd > newStart) { clash = true; break; }
  }

  return [{ json: { slotFree: !clash, verified: true } }];
} catch (err) {
  return [{ json: { slotFree: true, verified: false, note: 'evaluation error: ' + err.message } }];
}

try {
  var prep = $('Process Lookups').first().json || {};
  return [{ json: {
    toolCallId: prep.toolUseId || '',
    result: 'SLOT NO LONGER AVAILABLE. Someone else took that time while you were talking. Do NOT tell the customer it is booked. Apologise briefly, then call check_availability again on your next message to offer fresh times.'
  } }];
} catch (e) {
  return [{ json: {
    toolCallId: '',
    result: 'SLOT NO LONGER AVAILABLE. Do not confirm the booking. Apologise and offer to look for other times.'
  } }];
}

try {
  var d = $('Compute Booking Times').first().json || {};
  var reason = d.rejectReason || 'outside-hours';
  var when = (d.friendlyDate || 'that day') + ' at ' + (d.slotLabel || 'that time');
  var hours = 'Survey visits run Monday to Friday 9am to 5pm only, with at least 48 hours notice. We do not survey on Saturdays, Sundays or bank holidays.';
  var msg;

  if (reason === 'bank-holiday') {
    msg = 'NOT BOOKED. ' + when + ' falls on a bank holiday and we do not carry out surveys then. ' + hours + ' Apologise, do NOT say it is booked, and offer to check another day.';
  } else if (reason === 'closed-day') {
    msg = 'NOT BOOKED. We are closed on ' + (d.friendlyDate || 'that day') + '. ' + hours + ' Apologise, do NOT say it is booked, and offer to check another day.';
  } else if (reason === 'too-soon') {
    msg = 'NOT BOOKED. ' + when + ' is inside our 48 hour notice window, and we need at least 48 hours to arrange a surveyor. Apologise, do NOT say it is booked, and offer the next working day.';
  } else if (reason === 'bad-time') {
    msg = 'NOT BOOKED. That time was not recognised as one of our bookable slots. Do NOT say it is booked. Ask the customer to pick a slot on the hour between 9am and 5pm, and offer to check what is free.';
  } else if (reason === 'error') {
    msg = 'NOT BOOKED. A system error stopped the booking being processed. Apologise, do NOT claim it is booked, and ask them to try again shortly.';
  } else {
    msg = 'NOT BOOKED. ' + when + ' is outside our survey hours. ' + hours + ' Apologise, do NOT say it is booked, and offer a time inside those hours.';
  }

  return [{ json: { toolCallId: d.toolUseId || '', result: msg } }];
} catch (e) {
  return [{ json: { toolCallId: '', result: 'NOT BOOKED. That time is outside our survey hours. Do not confirm a booking. Offer Monday to Friday 9am to 5pm, at least 48 hours ahead, instead.' } }];
}

// BUG-R34: replaced the Sheets append node, which resolved the target row itself and
// lost rows when two bookings landed together. Google's values:append allocates the
// row server-side. It writes POSITIONALLY, so we map onto the LIVE header row by name.
try {
  var p = $('Process Lookups').first().json || {};
  var cal = {};
  try { cal = $('Create Calendar Event').first().json || {}; } catch (x) {}
  var hdrResp = $input.first() ? ($input.first().json || {}) : {};

  // Documented A:Q order from GOOGLE_SHEETS_SCHEMA.md, used only if the live read failed.
  var fallback = ['Name', 'Phone', 'Email', 'Service', 'Address', 'Date', 'Time', 'Status', 'CalendarEventId', 'Booked At', 'Notes', 'AppointmentTimeISO', 'Reminder1Sent', 'Reminder2Sent', 'ConfirmedAt', 'CancelledAt', 'Booked By'];

  var headers = [];
  if (hdrResp && hdrResp.values && hdrResp.values.length > 0 && hdrResp.values[0] && hdrResp.values[0].length > 0) {
    for (var h = 0; h < hdrResp.values[0].length; h++) { headers.push(String(hdrResp.values[0][h]).trim()); }
  }
  var headersVerified = headers.length > 0;

  // CalendarEventId is the update match key for every later cancel/reschedule.
  // A row without it is unmaintainable, so treat its absence as a failed header read.
  var criticalOk = headers.indexOf('Phone') !== -1 && headers.indexOf('CalendarEventId') !== -1;
  var usedFallback = false;
  if (!headersVerified || !criticalOk) { headers = fallback; usedFallback = true; }

  var map = {
    'Name': p.name || '',
    'Phone': p.phone || '',
    'Email': p.email || '',
    'Service': p.service || '',
    'Address': p.address || '',
    'Date': p.friendlyDate || '',
    'Time': p.slotLabel || '',
    'Status': 'confirmed',
    'CalendarEventId': cal.id || '',
    'Booked At': p.bookedAt || new Date().toISOString(),
    'Notes': '',
    'AppointmentTimeISO': p.startISO || '',
    'Reminder1Sent': '',
    'Reminder2Sent': '',
    'ConfirmedAt': '',
    'CancelledAt': '',
    'Booked By': 'chatbot'
  };

  var row = [];
  for (var i = 0; i < headers.length; i++) {
    if (Object.prototype.hasOwnProperty.call(map, headers[i])) { row.push(map[headers[i]]); }
    else { row.push(''); }
  }

  return [{ json: { values: [row], headers: headers, headersVerified: headersVerified, usedFallback: usedFallback, calendarEventId: cal.id || '' } }];
} catch (e) {
  return [{ json: { values: [], buildError: e.message } }];
}

// BUG-R36: the two appendOrUpdate writes (Core then First-Touch) raced both with each
// other and with other customers. Observed live: customer A's Core row was overwritten
// by customer B's Core row, then A's First-Touch appended a NEW row holding only its own
// four fields — a hollow lead with a phone and nothing else, while the booking row was fine.
// Now: ONE read, ONE merged row, then either a targeted row update or an atomic append.
try {
  var p = $('Process Lookups').first().json || {};
  var resp = $input.first() ? ($input.first().json || {}) : {};
  var phone = String(p.phone || '');
  var digits = phone.replace(/[^0-9]/g, '');

  var grid = (resp && resp.values) ? resp.values : [];
  var headers = [];
  if (grid.length > 0 && grid[0]) {
    for (var h = 0; h < grid[0].length; h++) { headers.push(String(grid[0][h]).trim()); }
  }
  if (headers.length === 0) {
    return [{ json: { skip: true, reason: 'could not read Clients headers', exists: false, values: [] } }];
  }

  var phoneIdx = headers.indexOf('Phone');
  if (phoneIdx === -1) {
    return [{ json: { skip: true, reason: 'Clients sheet has no Phone column', exists: false, values: [] } }];
  }

  // Locate an existing row for this phone, comparing digits only.
  var existingRow = null;
  var sheetRowNumber = 0;
  for (var r = 1; r < grid.length; r++) {
    var cell = grid[r] && grid[r][phoneIdx] !== undefined ? String(grid[r][phoneIdx]) : '';
    if (cell && cell.replace(/[^0-9]/g, '') === digits && digits !== '') {
      existingRow = grid[r];
      sheetRowNumber = r + 1;
      break;
    }
  }
  var exists = existingRow !== null;

  // Start from what is already there so an update never blanks a column we do not own.
  var row = [];
  for (var c = 0; c < headers.length; c++) {
    var v = (exists && existingRow[c] !== undefined) ? existingRow[c] : '';
    row.push(v);
  }

  function put(col, val) {
    var i = headers.indexOf(col);
    if (i !== -1) { row[i] = val; }
  }
  function putIfEmpty(col, val) {
    var i = headers.indexOf(col);
    if (i !== -1 && (row[i] === '' || row[i] === undefined || row[i] === null)) { row[i] = val; }
  }

  // Core fields — always written on a booking.
  put('Phone', phone);
  put('Name', p.name || '');
  put('Email', p.email || '');
  put('Status', 'booked');
  put('Last Outcome', 'booked');
  put('Upcoming Appointment', (p.friendlyDate || '') + ' at ' + (p.slotLabel || ''));
  put('Last Contact', new Date().toISOString());
  put('Last Channel', 'chatbot');
  put('Service Interest', p.service || '');

  // First-touch fields — set once and never overwritten, per GOOGLE_SHEETS_SCHEMA.md.
  putIfEmpty('Lead Source', 'WhatsApp Chat');
  putIfEmpty('Created At', p.bookedAt || new Date().toISOString());
  putIfEmpty('SMS Opt-Out', 'N');
  putIfEmpty('Sequence Step', '0');

  // Range for a targeted update, e.g. Clients!A5:T5
  function colLetter(n) {
    var s = '';
    while (n > 0) { var m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = Math.floor((n - 1) / 26); }
    return s;
  }
  var lastCol = colLetter(headers.length);
  var updateRange = exists ? ($('⚙️ Client Config').first().json.clientsTab + '!A' + sheetRowNumber + ':' + lastCol + sheetRowNumber) : '';

  return [{ json: { skip: false, exists: exists, sheetRowNumber: sheetRowNumber, updateRange: updateRange, headers: headers, values: [row] } }];
} catch (e) {
  return [{ json: { skip: true, reason: 'build error: ' + e.message, exists: false, values: [] } }];
}

